INSERT OR IGNORE INTO research_countries (code,name,region) VALUES ('MY','Malaysia','Asia');

-- Add a complete new mapping only when no manual mapping or unmapped pin exists.
WITH requested(raw_value,target) AS (VALUES
  ('Hong Kong / Malaysia','HK'),
  ('Hong Kong / Malaysia','MY')),
missing(raw_value) AS MATERIALIZED (
  SELECT DISTINCT r.raw_value FROM requested r
  WHERE NOT EXISTS (SELECT 1 FROM research_taxonomy_overrides o
    WHERE o.kind = 'fund_hq' AND o.raw_value = r.raw_value)
)
INSERT OR IGNORE INTO research_taxonomy_overrides (kind,raw_value,target,method,note)
SELECT 'fund_hq',r.raw_value,r.target,'manual','D7326: verified HQ countries in the worldwide manager evidence manifest.'
FROM requested r JOIN missing m ON m.raw_value = r.raw_value;

